-- Sync the prize list and criteria to the live Supabase database.
-- Safe to run any time: updates ONLY the 'prizes' collection; leaves teams,
-- members, scores, tickets, and the store untouched. Run in the Supabase SQL
-- editor or: psql "$DATABASE_URL" -f supabase/sync_prizes.sql
-- Generated from src/data/prizes.json by tools/gen_sync.mjs.
insert into public.collections (name, data)
values ('prizes', $prizes$[{"id":"pz-trees-podium","name":"From Trees to Tech: Top Three","tier":"Camp","desc":"The three highest-scoring From Trees to Tech teams of the week.","criteria":"2026 live-event override: top three after each team's lowest quarter of entered scores is canceled. The original reviewed kit used best 9 of 12 primary stations."},{"id":"pz-trees-growth","name":"From Trees to Tech: Growth Award","tier":"Growth","desc":"The Trees team that climbed the most across the week.","criteria":"Largest gain from early to late activities, including comeback bonuses."},{"id":"pz-py-podium","name":"PY-STEM: Top Three","tier":"Camp","desc":"The three highest-scoring PY-STEM teams of the week.","criteria":"2026 live-event override: top three after each team's lowest quarter of entered non-CRANK scores is canceled; CRANK is then added in full. The original reviewed kit used best 9 of 12 primary stations."},{"id":"pz-py-growth","name":"PY-STEM: Growth Award","tier":"Growth","desc":"The PY-STEM team that climbed the most across the week.","criteria":"Largest gain from early to late activities, including comeback bonuses."},{"id":"pz-py-crank","name":"PY-STEM: Crank Championship","tier":"Camp","desc":"A 2026 live addition: the Friday crank-machine showdown, judged at the final showcase.","criteria":"Three judges each hold up 0 to 10 for five things: motion, reliability, engineering, aesthetics, and the pitch. The card total is doubled, so the championship is worth up to 300 points, because teams built their machines all week and a strong showing can move a team back up the leaderboard. It always counts: it is never part of the canceled quarter."}]$prizes$::jsonb)
on conflict (name) do update set data = excluded.data;
